// Some portions generated by Claude Code
package org.eclipse.rdf4j.tools.lmdb.bulk;

import java.io.IOException;
import java.nio.file.FileStore;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Watches how much room is left where a bulk load writes, and kills this JVM before the disk runs out.
 * <p>
 * A load that fills its volume corrupts nothing — the workspace is resumable — but it can take a long time to fail and
 * it takes the rest of the machine down with it. Dying early on a still-usable disk is the cheaper outcome, so the
 * monitor reads the free space every {@value #RELAXED_CHECK_MILLIS} ms, tightens to every {@value #URGENT_CHECK_MILLIS}
 * ms once less than {@link #URGENT_FREE_BYTES} is left, and ends the process below {@link #FATAL_FREE_BYTES}. Whatever
 * the reading cadence, it reports the free space no more than once every {@value #LOG_INTERVAL_MILLIS} ms.
 */
final class DiskSpaceMonitor implements AutoCloseable {

	static final long GIB = 1024L * 1024L * 1024L;
	static final long FATAL_FREE_BYTES = 50L * GIB;
	static final long URGENT_FREE_BYTES = 100L * GIB;
	static final long RELAXED_CHECK_MILLIS = 60_000L;
	static final long URGENT_CHECK_MILLIS = 1_000L;
	static final long LOG_INTERVAL_MILLIS = 60_000L;

	private static final String THREAD_NAME = "lmdb-bulk-load-disk-monitor";
	private static final long STOP_TIMEOUT_MILLIS = 5_000L;

	private final Consumer<String> log;
	private final Runnable terminator;
	private final FreeSpace probe;
	private final CountDownLatch stopped = new CountDownLatch(1);
	private volatile List<Path> locations = List.of();
	private volatile Thread thread;
	/** Only ever read and written by whichever single thread drives {@link #check(long)}. */
	private Long lastLogMillis;

	/**
	 * @param probe reads the free space, or {@code null} to read the watched locations off the file system
	 */
	DiskSpaceMonitor(Consumer<String> log, Runnable terminator, FreeSpace probe) {
		this.log = Objects.requireNonNull(log, "log");
		this.terminator = Objects.requireNonNull(terminator, "terminator");
		this.probe = probe == null ? this::tightestReading : probe;
	}

	/**
	 * Starts watching {@code locations} on a daemon thread.
	 */
	static DiskSpaceMonitor started(Consumer<String> log, Runnable terminator, Path... locations) {
		return new DiskSpaceMonitor(log, terminator, null).watch(locations).start();
	}

	/**
	 * A monitor that observes nothing and kills nothing, for a caller that does not own the JVM it loads in.
	 */
	static DiskSpaceMonitor inert() {
		return new DiskSpaceMonitor(message -> {
		}, () -> {
		}, null);
	}

	/**
	 * Replaces the watched locations, ignoring any that are {@code null}. A call that names nothing at all leaves the
	 * previous locations in place, so the guess a monitor starts with is only ever replaced by something better rather
	 * than by nothing.
	 */
	DiskSpaceMonitor watch(Path... locations) {
		if (locations == null) {
			return this;
		}
		List<Path> replacement = new ArrayList<>(locations.length);
		for (Path location : locations) {
			if (location == null) {
				continue;
			}
			Path normalized = location.toAbsolutePath().normalize();
			if (!replacement.contains(normalized)) {
				replacement.add(normalized);
			}
		}
		if (!replacement.isEmpty()) {
			this.locations = List.copyOf(replacement);
		}
		return this;
	}

	List<Path> watchedLocations() {
		return locations;
	}

	DiskSpaceMonitor start() {
		Thread monitoring = new Thread(this::monitor, THREAD_NAME);
		// A daemon: the loader decides when the run is over, and a monitor is never a reason to stay alive.
		monitoring.setDaemon(true);
		thread = monitoring;
		monitoring.start();
		return this;
	}

	Thread monitoringThread() {
		return thread;
	}

	/**
	 * Takes one reading and acts on it.
	 *
	 * @param nowMillis the time this reading is taken, against which the reporting interval is measured
	 * @return how long to wait before reading again
	 */
	long check(long nowMillis) {
		Reading reading;
		try {
			reading = probe.read();
		} catch (IOException unreadable) {
			report(nowMillis, "Could not read the free disk space: " + unreadable);
			return RELAXED_CHECK_MILLIS;
		}
		if (reading == null) {
			if (locations.isEmpty()) {
				// Nothing to watch yet, because the run has not said where it writes. Guessing at a volume here is
				// worse than waiting: killing a load over a full disk it was never going to touch is the one failure
				// this monitor must not have. Look again shortly instead of waiting out a whole interval.
				return URGENT_CHECK_MILLIS;
			}
			report(nowMillis, "Could not read the free disk space for any of " + locations);
			return RELAXED_CHECK_MILLIS;
		}
		if (reading.usableBytes() < FATAL_FREE_BYTES) {
			// Reported outside the interval: this is the last thing the process says.
			lastLogMillis = nowMillis;
			log.accept(describe(reading) + ", under the " + LmdbBulkLoad.describeBytes(FATAL_FREE_BYTES)
					+ " floor; killing the bulk loader JVM");
			terminator.run();
			return URGENT_CHECK_MILLIS;
		}
		if (reading.usableBytes() < URGENT_FREE_BYTES) {
			report(nowMillis, describe(reading) + ", closing on the " + LmdbBulkLoad.describeBytes(FATAL_FREE_BYTES)
					+ " floor this load is killed at");
			return URGENT_CHECK_MILLIS;
		}
		report(nowMillis, describe(reading));
		return RELAXED_CHECK_MILLIS;
	}

	/**
	 * @return the watched location with the least room left, or {@code null} when none of them can be read
	 */
	Reading tightestReading() {
		Reading tightest = null;
		Set<FileStore> visited = new HashSet<>();
		for (Path location : locations) {
			// A store the loader has not created yet still lands on some volume, and that volume is the one that has
			// to hold it.
			Path existing = nearestExistingAncestor(location);
			if (existing == null) {
				continue;
			}
			try {
				FileStore store = Files.getFileStore(existing);
				if (!visited.add(store)) {
					continue;
				}
				long usable = store.getUsableSpace();
				if (tightest == null || usable < tightest.usableBytes()) {
					tightest = new Reading(store + " at " + existing, usable);
				}
			} catch (IOException unreadable) {
				// A location whose file store will not answer is skipped rather than taken for a full disk.
			}
		}
		return tightest;
	}

	@Override
	public void close() {
		stopped.countDown();
		Thread monitoring = thread;
		if (monitoring == null) {
			return;
		}
		try {
			monitoring.join(STOP_TIMEOUT_MILLIS);
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	private void monitor() {
		while (true) {
			long delay;
			try {
				delay = check(System.currentTimeMillis());
			} catch (RuntimeException failure) {
				// Watching a disk badly beats not watching it at all, so a broken reading costs one interval.
				log.accept("Could not check the free disk space: " + failure);
				delay = RELAXED_CHECK_MILLIS;
			}
			try {
				if (stopped.await(delay, TimeUnit.MILLISECONDS)) {
					return;
				}
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				return;
			}
		}
	}

	private void report(long nowMillis, String message) {
		if (lastLogMillis == null || nowMillis - lastLogMillis >= LOG_INTERVAL_MILLIS) {
			lastLogMillis = nowMillis;
			log.accept(message);
		}
	}

	private static String describe(Reading reading) {
		return "Free disk space " + LmdbBulkLoad.describeBytes(reading.usableBytes()) + " on " + reading.location();
	}

	private static Path nearestExistingAncestor(Path location) {
		for (Path candidate = location; candidate != null; candidate = candidate.getParent()) {
			if (Files.exists(candidate)) {
				return candidate;
			}
		}
		return null;
	}

	/**
	 * Reads how much room the watched locations still have.
	 */
	@FunctionalInterface
	interface FreeSpace {

		/**
		 * @return the watched location with the least room left, or {@code null} when none of them can be read
		 */
		Reading read() throws IOException;
	}

	/**
	 * How much room one location still has.
	 */
	record Reading(String location, long usableBytes) {
	}
}
